<script setup lang="ts">const { data }=await useFetch('/api/news'); const format=(value:string)=>{const d=new Date(value);return `${d.toLocaleDateString()} ${d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}`}</script>
<template><div><section class="container page-content"><div class="text-center"><h3>Recent Local News</h3><p>Powered by: <a href="https://newsroom.calgary.ca/">The Calgary Newsroom</a></p></div><hr><div v-if="data?.newsError" class="text-center error" role="alert">Local news is temporarily unavailable.</div><div v-else data-testid="news-list"><div class="row"><div class="col-6"><a v-for="item in data?.news.slice(0,1)" :key="item.href" class="news-panel featured" :href="item.href"><h6>{{ item.title }}.</h6><p><small>{{ format(item.pubdate) }}</small></p></a></div><div class="col-6"><a v-for="item in data?.news.slice(1,4)" :key="item.href" class="news-panel" :href="item.href"><h6>{{ item.title }}.</h6><p><small>{{ format(item.pubdate) }}</small></p></a></div></div><div class="row"><div v-for="item in data?.news.slice(4,7)" :key="item.href" class="col-4"><a class="news-panel" :href="item.href"><h6>{{item.title}}.</h6><p><small>{{format(item.pubdate)}}</small></p></a></div></div><div class="row justify-center"><div v-for="item in data?.news.slice(7,11)" :key="item.href" class="col-3"><a class="news-panel" :href="item.href"><h6>{{item.title}}.</h6><p><small>{{format(item.pubdate)}}</small></p></a></div></div></div><br><br></section><section class="traffic"><div class="container"><div class="row justify-around"><div class="col-6"><CalgaryMap title="Traffic Incidents" :items="data?.traffic||[]" show-started /></div><div class="col-6"><CalgaryMap title="Current Detours" :items="data?.detours||[]" /></div></div></div></section></div></template>
